import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Transports actuels et restrictions de plateforme","description":"","frontmatter":{"title":"Transports actuels et restrictions de plateforme","docId":"developer.transports","translationKey":"developer.transports","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","translationRevision":"ba5fe61d36b0954d333cff3b3700fa2901de9349978c051ae84816cbfac1054c","order":200},"headers":[],"relativePath":"fr/developer/transports.md","filePath":"fr/developer/transports.md","lastUpdated":1795735295000}`),a={name:`fr/developer/transports.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Transports actuels et restrictions de plateforme <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to “Transports actuels et restrictions de plateforme”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Choisir le transport qui existe réellement pour la compilation et la plateforme ciblées. Lisez l’<a href="./control-api.html">API de contrôle</a> et la <a href="./collaboration.html">collaboration</a>. Un transport porte des opérations sérialisées ; il ne doit pas introduire un second cœur ou accorder une autorité à lui seul.</p><h2 id="choose-the-boundary" tabindex="-1">Choisir la frontière <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to “Choisir la frontière”">​</a></h2><table tabindex="0"><thead><tr><th>Parcours</th><th>Implémentation actuelle</th><th>Limite importante</th></tr></thead><tbody><tr><td>WebView bureau</td><td>IPC Wry et client de contrôle partagé</td><td>La durée de vie de l’interface et des threads appartient au bureau</td></tr><tr><td>CLI locale</td><td>Socket Unix ou canal nommé Windows ; hôte stdio explicite</td><td>Même répertoire et même propriétaire de l’application</td></tr><tr><td>Navigateur local</td><td>Adaptateur loopback natif et <code>browser-transport.ts</code></td><td>Hôte natif appairé, pas un serveur distant public</td></tr><tr><td>Passerelle HTTPS/WSS authentifiée</td><td>Transports SDK/navigateur avec TLS, hello, autorisations et feature gates</td><td>Les commandes distantes exigent une autorisation explicite</td></tr><tr><td>Plugin de télécommande installable</td><td><code>tiktools.remote-control</code> sur un relais WSS avec <code>remote.controller.ticket</code></td><td>Propriété du plugin ; aucun code distant n’est compilé dans l’hôte</td></tr></tbody></table><p>L’interface TypeScript se trouve dans <code>src/web/shared/api/control-transport.ts</code>. La télécommande est un plugin installable, et non une partie du binaire hôte : chaque commande passe par <code>HostCallPolicy</code> (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>). Cette compilation ne contient ni transport pair/RTC natif ni lien hôte Cloud Teams.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspecter la route sélectionnée <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to “Inspecter la route sélectionnée”">​</a></h2><p>Découvrez les méthodes et capacités prises en charge par l’hôte connecté avant l’appairage ou l’affichage d’une action de contrôle :</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span></code></pre></div><p>L’appairage et les autorisations appartiennent au plugin : le ticket de contrôleur est de courte durée et à usage unique, et <code>remote.grant.list</code> / <code>remote.grant.revoke</code> font foi. Une connexion relais prouve seulement le transport, jamais l’autorité RPC.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et statut <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Résultat attendu et statut”">​</a></h2><p>L’IPC local et le transport bureau sont des chemins établis. La télécommande fonctionne via le plugin installable et un relais authentifié ; ce n’est pas un second runtime hôte. Les codes de connexion sont relayés vers les appareils connectés avec une durée de vie de cinq minutes, avec OAuth en repli lorsqu’aucun compte n’est configuré. L’IPC local Android fonctionne avec les outils instrumentés <code>mobile</code> (<code>info</code> / <code>exec</code> / <code>tty</code>) ; les addons natifs et WebViews de bureau y restent indisponibles.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to “Récupération”">​</a></h2><p>Considérez la déconnexion comme une incertitude possible pour les opérations acceptées. La reconnexion doit invalider les projections privées, renégocier l’identité et reprendre ou figer les flux bornés. Ne réduisez jamais les vérifications de certificat et ne revenez pas silencieusement à un propriétaire local après un échec distant. Les tickets expirés et les autorisations révoquées doivent échouer en fermeture.</p><h2 id="operational-details" tabindex="-1">Détails opérationnels <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Détails opérationnels”">​</a></h2><p>Gardez les autorisations au minimum privilège et à durée limitée ; vérifiez-les à chaque reconnexion. Diagnostiquez séparément l’identité, l’expiration du ticket, la portée de l’autorisation, l’accessibilité du relais et la taille des trames. Les trames trop grandes échouent à la validation du cadrage plutôt que de devenir des RPC partielles. Testez les sessions modifiées ou révoquées avec des fixtures avant une acceptation réelle sur deux appareils.</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};